/**
 * PROMOTION GATE — the git prompt source-of-truth loader.
 *
 * `Prompts/canonical/manifest.json` is the committed snapshot of what PMS
 * serves: per prompt, its served version and `cee_content_hash_16`
 * (= sha256(content)[:16], `src/prompts/loader.ts:33`). The gate treats that
 * hash as the promoted-version IDENTITY.
 *
 * ⚠ HONEST LIMITATION (trap 18): the manifest is a LAGGING mirror of live PMS,
 * regenerated by a human. A staging promotion made only via the admin API
 * (`PATCH /admin/prompts/:id {stagingVersion}`) that never regenerates+commits
 * this file is NOT visible to this CI gate. This gate makes drift impossible in
 * the GIT source of truth; closing the live-only hole is the runtime seam
 * (`src/routes/admin.prompts.ts`), sequenced separately. Stated so no reader
 * mistakes a green gate for "nothing was promoted live".
 */

import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { ManifestPromptEntry } from './types.js';

const HERE = dirname(fileURLToPath(import.meta.url));

/** Repo root, from this module's location (tools/orchestrator-eval/src/promotion-gate). */
export const REPO_ROOT = join(HERE, '..', '..', '..', '..');

export const CANONICAL_MANIFEST_PATH = join(
  REPO_ROOT,
  'Prompts',
  'canonical',
  'manifest.json',
);

/**
 * sha256 (first 16 hex chars) of a prompt's bytes — the manifest's OWN format
 * (`_meta.served_hash_algo`, `src/prompts/loader.ts:33`). This is a hash
 * function, not a rule mirror: the algorithm is fixed by the runtime loader.
 */
export function promptHash16(text: string): string {
  return createHash('sha256').update(text, 'utf-8').digest('hex').slice(0, 16);
}

/** Hash the canonical export at `path` the manifest's way. */
export function hashCanonicalFile(path: string): string {
  return promptHash16(readFileSync(path, 'utf-8'));
}

interface RawManifestPrompt {
  readonly key?: unknown;
  readonly file?: unknown;
  readonly served_version?: unknown;
  readonly cee_content_hash_16?: unknown;
  readonly served_hash_verified?: unknown;
}

/**
 * Load the PMS prompts from the manifest.
 *
 * FAIL-LOUD on a manifest that yields zero PMS prompts, or an entry missing the
 * fields the gate keys on: a manifest the loader silently read as empty would
 * make every task UNGATED and the whole gate pass by measuring nothing (trap
 * 13). An unreadable/mis-shaped manifest is a hard error, never an empty list.
 */
export function loadManifestPrompts(
  manifestPath: string = CANONICAL_MANIFEST_PATH,
): ManifestPromptEntry[] {
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(manifestPath, 'utf-8'));
  } catch (err) {
    throw new Error(
      `promotion-gate: cannot read prompt manifest at ${manifestPath}: ` +
        `${err instanceof Error ? err.message : String(err)}`,
    );
  }
  const root = parsed as { pms_prompts?: unknown } | null;
  const list = root && Array.isArray(root.pms_prompts) ? (root.pms_prompts as RawManifestPrompt[]) : null;
  if (!list) {
    throw new Error(
      `promotion-gate: manifest ${manifestPath} has no "pms_prompts" array — refusing to run ` +
        'the gate over an empty prompt set (that would pass by measuring nothing).',
    );
  }
  const entries: ManifestPromptEntry[] = [];
  for (const p of list) {
    const key = p.key;
    const file = p.file;
    const version = p.served_version;
    const hash = p.cee_content_hash_16;
    if (
      typeof key !== 'string' ||
      typeof file !== 'string' ||
      typeof version !== 'number' ||
      typeof hash !== 'string'
    ) {
      throw new Error(
        `promotion-gate: manifest entry is missing key/file/served_version/cee_content_hash_16: ` +
          `${JSON.stringify(p)}`,
      );
    }
    entries.push({
      task: key,
      servedVersion: version,
      servedHash: hash,
      canonicalFile: join(REPO_ROOT, file),
      servedHashVerified: p.served_hash_verified === true,
    });
  }
  if (entries.length === 0) {
    throw new Error(
      `promotion-gate: manifest ${manifestPath} parsed to ZERO pms_prompts — refusing (vacuous).`,
    );
  }
  return entries;
}
